/**
 * 补丁：为「关于"暗网动画"旧帖补充」评论区 121L 换图
 * 将 121L 中的文字「【图片·厨房背影】」删除，替换为指定图片。
 * 楼层规则：楼主=1L，评论从 2L 起；121L 对应升序排列的第 119 条评论。
 */
Storage.ready().then(async function () {
  var PATCH_KEY = 'darknetComment121Patch_v1';
  if (localStorage.getItem(PATCH_KEY)) return;

  var IMAGE_DATAURL = "data:image/jpeg;base64,";
  var MARKER = '【图片·厨房背影】';

  var posts = Storage.getPosts();
  var post = null;
  for (var i = 0; i < posts.length; i++) {
    var t = posts[i].title || '';
    if (t.indexOf('暗网动画') !== -1 && t.indexOf('旧帖补充') !== -1) { post = posts[i]; break; }
  }
  if (!post) { console.log('[补丁121] 未找到目标帖子'); return; }

  var all = Storage.getComments();
  var asc = all
    .filter(function (c) { return c.postId === post.id; })
    .sort(function (a, b) { return a.createdAt - b.createdAt; });

  var target = asc[119];
  if (!target || (target.content || '').indexOf(MARKER) === -1) {
    target = null;
    for (var j = 0; j < asc.length; j++) {
      if ((asc[j].content || '').indexOf(MARKER) !== -1) { target = asc[j]; break; }
    }
  }
  if (!target) { console.log('[补丁121] 未找到含「' + MARKER + '」的评论'); return; }

  target.content = (target.content || '').split(MARKER).join('').trim();
  target.images = (target.images || []).concat([IMAGE_DATAURL]);

  await Storage.saveComments(all);
  localStorage.setItem(PATCH_KEY, '1');
  console.log('[补丁121] 评论换图完成');
});
